/** What each tappable layer runs (for tools and tests that play the prototype without a screen). */
export const TAPS: Record<string, { rule: string; it?: string }[]> = {"rideChooseARide||body.2.children.0|ListItem":[{"rule":"r1","it":"body.2.children.0"}],"rideChooseARide||body.2.children.1|ListItem":[{"rule":"r1","it":"body.2.children.1"}],"rideChooseARide||body.2.children.2|ListItem":[{"rule":"r1","it":"body.2.children.2"}],"rideChooseARide||footer.0|Button/Primary":[{"rule":"r2"}],"rideChooseARide|pickup|footer.0|Button/Primary":[{"rule":"r3"},{"rule":"r5"}],"rideChooseARide|pickup|footer.1|Button/Tertiary":[{"rule":"r4"}]};

export interface Entry {
  screen: ScreenId;
  /** Its parts that were open, in the order they opened. */
  open: string[];
  /** What the screen remembers on this visit (see INIT). */
  data: Record<string, unknown>;
  /** The item each open part is about (a dish's options: the dish). */
  ctx: Record<string, string>;
  /** How it was gone to, the last time it was (not by going back): a pushed screen pops the way it came. */
  came?: Via["kind"];
}

export interface State extends Entry {
  /** Bumps on every move, so each visit is its own element that can enter and leave. */
  visit: number;
  history: Entry[];
  via?: Via;
  /** Shared layers match within a group: smart transitions stay in it, other kinds start a new one. */
  group: number;
  anchors: Record<string, Box>;
  /** What the app remembers across screens. */
  app: AppData;
  /** A scroll a rule asked for (the screen scrolls when `n` changes). */
  scrollTo?: { y: number; n: number };
  /** How close that scroll has come: while it heads there, what the rule picked (a section) stays picked. */
  held?: number;
}

/** Where the prototype starts: a screen that draws a list starts with the lines its design shows (APP_SEED). */
export const initial = (screen: ScreenId): State => ({ screen, open: [], data: INIT[screen](), ctx: {}, visit: 0, history: [], group: 0, anchors: {}, app: { ...APP_INIT(), ...APP_SEED[screen]?.() } });

const isBar = (screen: ScreenId, part: string) => PARTS[screen]?.[part]?.kind === "bar";
/** The topmost open overlay (bars aren't overlays). */
const topOverlay = (n: State) => [...n.open].reverse().find((p) => !isBar(n.screen, p));

function move(n: State, to: ScreenId | "back", via: Via): State {
  if (to === "back") {
    const prev = n.history[n.history.length - 1];
    if (!prev) return n;
    // Back to a screen as it was left: what it remembered, and its bars.
    return { ...n, ...prev, visit: n.visit + 1, history: n.history.slice(0, -1), via: { ...via, back: true, dir: SCREENS[prev.screen].dir }, group: via.kind === "smart" ? n.group : n.group + 1, anchors: {}, scrollTo: undefined, held: undefined };
  }
  // The screen left keeps its bars for when you come back; its overlays close.
  const left: Entry = { screen: n.screen, open: n.open.filter((p) => isBar(n.screen, p)), data: n.data, ctx: n.ctx, came: n.came };
  return { ...n, screen: to, open: [], data: INIT[to](), ctx: {}, came: via.kind, visit: n.visit + 1, history: [...n.history, left], via: { ...via, dir: SCREENS[to].dir }, group: via.kind === "smart" ? n.group : n.group + 1, anchors: {}, scrollTo: undefined, held: undefined };
}

/** Open a part, about an item when it has one; what it keeps for itself starts over. */
function openPart(n: State, part: string, anchor?: Box, item?: string): State {
  if (!PARTS[n.screen]?.[part]) return n;
  const fresh = INIT[n.screen]();
  const reset = Object.fromEntries((RESETS[n.screen]?.[part] ?? []).map((v) => [v, fresh[v]]));
  return {
    ...n,
    open: n.open.includes(part) ? n.open : [...n.open, part],
    anchors: anchor ? { ...n.anchors, [part]: anchor } : n.anchors,
    ctx: item !== undefined ? { ...n.ctx, [part]: item } : n.ctx,
    data: { ...n.data, ...reset },
  };
}

/** The screen scrolled: values that follow scrolling (a compact header, the section in view). */
function scrolled(n: State, y: number, max = Infinity): State {
  const sc = SCROLL[n.screen];
  if (!sc) return n;
  let data = n.data;
  for (const [v, at] of sc.past) if (data[v] !== y > at) data = { ...data, [v]: y > at };
  // A section a tap picked stays picked while the scroll heads there (it may stop short, at the bottom), until you scroll away.
  let held = n.held;
  if (held !== undefined && n.scrollTo) {
    const d = Math.abs(y - Math.min(n.scrollTo.y, max));
    held = d > held + 1 ? undefined : Math.min(held, d);
  }
  if (sc.spy && held === undefined) {
    const { v, marks } = sc.spy;
    // Sections too near the end to reach the top get their turn as the scroll ends: the line that picks one slides down to the last.
    const over = marks.length && max < Infinity ? marks[marks.length - 1][1] - max : 0;
    const ramp = Math.min(over, max);
    const line = y + 1 + (over > 0 && ramp > 0 ? over * Math.min(1, Math.max(0, (y - (max - ramp)) / ramp)) : 0);
    let id = marks[0]?.[0] ?? null;
    for (const [sid, at] of marks) if (line >= at) id = sid;
    if (data[v] !== id) data = { ...data, [v]: id };
  }
  return data === n.data && held === n.held ? n : { ...n, data, held };
}

/** One step of the prototype: what an action does to where you are (pure; exported for tests and tools). */
export function step(n: State, a: Action, anchor?: Box): State {
  switch (a.do) {
    case "open":
      return n.open.includes(a.part) ? n : openPart(n, a.part, anchor);
    case "close": {
      const part = a.part ?? topOverlay(n);
      return part && n.open.includes(part) ? { ...n, open: n.open.filter((p) => p !== part) } : n;
    }
    case "back": {
      const top = topOverlay(n);
      return top ? { ...n, open: n.open.filter((p) => p !== top) } : move(n, "back", BACK);
    }
    case "go":
      return move(n, a.to, a.via);
    case "run": {
      const rule = RULES[n.screen]?.[a.rule];
      return rule ? rule(n, a.it, anchor) : n;
    }
    case "scrolled":
      return scrolled(n, a.y, a.max);
  }
}

/** Above the screen and its pinned bars; only what's open takes taps. */
const LAYER: CSSProperties = { position: "absolute", inset: 0, zIndex: 20, pointerEvents: "none" };
/** Scrims dim with black, as the platform's do. */
const SCRIM: CSSProperties = { position: "absolute", inset: 0, pointerEvents: "auto", backgroundColor: "#000" };
const CENTRE: CSSProperties = { position: "absolute", inset: 0, display: "grid", placeItems: "center", pointerEvents: "none" };

interface Size {
  width: number;
  height: number;
}

function Overlays({ s, size, act, reduced }: { s: State; size: Size; act: Act; reduced: boolean }) {
  const { screen, open, anchors } = s;
  const parts = PARTS[screen] ?? {};
  const shown = open.filter((p) => parts[p] && parts[p].kind !== "bar");
  return (
    <div style={LAYER}>
      <AnimatePresence>
        {shown.map((p) => (
          <Overlay key={screen + "/" + p} part={p} def={parts[p]} anchor={anchors[p]} size={size} act={act} s={s} reduced={reduced} />
        ))}
      </AnimatePresence>
    </div>
  );
}

function Overlay({ part, def, anchor, size, act, s, reduced }: { part: string; def: PartDef; anchor?: Box; size: Size; act: Act; s: State; reduced: boolean }) {
  const { Part, kind, dismiss } = def;
  const close = () => act({ do: "close", part });
  useEffect(() => {
    if (kind !== "toast" || !dismiss.includes("timer")) return;
    const t = setTimeout(() => act({ do: "close", part }), def.ms ?? 3000);
    return () => clearTimeout(t);
  }, [kind, dismiss, def.ms, act, part]);
  const body = <Part act={act} s={s} />;
  if (kind === "sheet")
    return (
      <Sheet def={def} size={size} close={close} reduced={reduced}>
        {body}
      </Sheet>
    );
  if (kind === "dialog")
    return (
      <Dialog def={def} close={close}>
        {body}
      </Dialog>
    );
  if (kind === "toast") return <Toast def={def}>{body}</Toast>;
  return (
    <Menu def={def} anchor={anchor} size={size} close={close}>
      {body}
    </Menu>
  );
}

/** Where a sheet sits: along the bottom, up to 48px from the top (a full one reaches it). */
const sheetBox = (def: PartDef): CSSProperties => ({ position: "absolute", insetInline: 0, bottom: 0, top: def.detent === "full" ? 48 : undefined, maxHeight: "calc(100% - 48px)", display: "flex", flexDirection: "column", pointerEvents: "auto" });

/**
 * Drags a sheet: it follows the pointer down and resists going up past where it rests
 * ((√(1 + over) − 1) × 2.5px, @gorhom/bottom-sheet's over-drag); let go, `release` gets where it is
 * and how fast it was going (px/s). A drag isn't a tap: what it began on stops looking pressed, and
 * the click it ends in is swallowed.
 */
function dragSheet(y: MotionValue<number>, on: { start?: () => void; release: (at: number, speed: number) => void }) {
  return (e: ReactPointerEvent<HTMLElement>) => {
    if (e.button !== 0) return;
    const el = e.currentTarget;
    // The stage may show the device smaller (CSS zoom): the pointer moves in its pixels, the sheet in the device's.
    const zoom = el.getBoundingClientRect().height / el.offsetHeight || 1;
    const from = e.clientY;
    const start = y.get();
    let dragging = false;
    const swallow = (c: Event) => {
      c.stopPropagation();
      c.preventDefault();
    };
    const move = (m: PointerEvent) => {
      const d = (m.clientY - from) / zoom;
      if (!dragging && Math.abs(d) < 8) return;
      if (!dragging) {
        dragging = true;
        unpress?.();
        window.addEventListener("click", swallow, true);
        on.start?.();
      }
      const at = start + d;
      y.set(at >= 0 ? at : -(Math.sqrt(1 - at) - 1) * 2.5);
    };
    const up = () => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", up);
      window.removeEventListener("pointercancel", up);
      if (!dragging) return;
      setTimeout(() => window.removeEventListener("click", swallow, true), 0);
      on.release(y.get(), y.getVelocity());
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", up);
    window.addEventListener("pointercancel", up);
  };
}

/** Where a menu goes: under what opened it (above when there's no room), on the side of the screen that is on, unfolding from that corner. */
function menuPlace(anchor: Box | undefined, size: Size, width: number) {
  const at = anchor ?? { x: size.width / 2, y: size.height / 3, w: 0, h: 0 };
  const start = at.x + at.w / 2 < size.width / 2;
  const below = at.y + at.h + 8 + 240 < size.height;
  const pos: CSSProperties = {
    position: "absolute",
    width,
    pointerEvents: "auto",
    ...(start ? { left: Math.max(8, at.x) } : { right: Math.max(8, size.width - at.x - at.w) }),
    ...(below ? { top: at.y + at.h + 8 } : { bottom: size.height - at.y + 8 }),
    transformOrigin: (below ? "top" : "bottom") + " " + (start ? "left" : "right"),
  };
  return { pos, below };
}

/** A menu's backdrop: nothing to see, it only takes the tap that closes the menu. */
const MENU_BACKDROP: CSSProperties = { position: "absolute", inset: 0, pointerEvents: "auto" };

/** A toast's place: along the bottom, above the home indicator, sliding from below the screen's edge. */
const TOAST_BOX: CSSProperties = { position: "absolute", insetInline: 0, bottom: 0, paddingBottom: 58, display: "flex", justifyContent: "center", pointerEvents: "none" };

/** Material 3 sheets on Android: MDC's m3_bottom_sheet_slide_in/out, the window dim (DimmerAnimationHelper), and @gorhom/bottom-sheet's Android settle. */
const SHEET = {
  rise: 0.2,
  dim: 0.32,
  project: 0.2,
  in: { duration: 0.4, ease: emphasized } as Transition,
  out: { duration: 0.35, ease: emphasized } as Transition,
  fadeOut: { duration: 0.3, ease: emphasized } as Transition,
  dimIn: { duration: 0.128, ease: "linear" } as Transition,
  dimOut: { duration: 0.112, ease: "linear" } as Transition,
  settle: { duration: 0.25, ease: outExpo } as Transition,
};

/**
 * A sheet, as Material 3 shows one on Android (React Navigation's BottomSheetAndroid): it rises a
 * fifth of the screen as it fades in, 400ms on the emphasized curve, as the screen behind dims to
 * 32% in 128ms; it leaves the same way in 350ms (fading over 300ms), the dim gone in 112ms. Dragged,
 * it follows and the dim with it; let go, it settles where it was heading (where it'd be 0.2s on:
 * gorhom's snapPoint) in 250ms, closing when that's past halfway down. With animations off it just
 * shows.
 */
function Sheet({ def, size, close, reduced, children }: { def: PartDef; size: Size; close: () => void; reduced: boolean; children: ReactNode }) {
  const [present, safeToRemove] = usePresence();
  const box = useRef<HTMLDivElement>(null);
  const height = useRef(size.height);
  const rise = size.height * SHEET.rise;
  const y = useMotionValue(reduced ? 0 : rise);
  const shown = useMotionValue(reduced ? 1 : 0);
  const dim = useMotionValue(reduced ? SHEET.dim : 0);
  // Dragged (and until it has settled after), the dim follows the sheet.
  const dragged = useRef(false);
  useMotionValueEvent(y, "change", (at) => {
    if (dragged.current) dim.set(SHEET.dim * Math.min(1, Math.max(0, 1 - at / height.current)));
  });
  useLayoutEffect(() => {
    height.current = box.current?.offsetHeight || size.height;
    if (reduced) return;
    const all = [animate(y, 0, SHEET.in), animate(shown, 1, SHEET.in), animate(dim, SHEET.dim, SHEET.dimIn)];
    return () => all.forEach((a) => a.stop());
  }, [reduced, size.height, y, shown, dim]);
  useEffect(() => {
    if (present) return;
    if (reduced) return void safeToRemove?.();
    const all = dragged.current ? [animate(y, height.current, SHEET.settle)] : [animate(y, rise, SHEET.out), animate(shown, 0, SHEET.fadeOut), animate(dim, 0, SHEET.dimOut)];
    void Promise.all(all).then(() => safeToRemove?.());
    return () => all.forEach((a) => a.stop());
  }, [present, reduced, rise, safeToRemove, y, shown, dim]);
  const release = (at: number, speed: number) => {
    if (at + SHEET.project * speed > height.current / 2) close();
    else void animate(y, 0, SHEET.settle).then(() => (dragged.current = false));
  };
  const drag = def.dismiss.includes("drag");
  return (
    <>
      <motion.div style={{ ...SCRIM, opacity: dim }} onClick={def.dismiss.includes("scrim") ? close : undefined} />
      <motion.div
        ref={box}
        role="dialog"
        aria-modal
        onPointerDown={drag ? dragSheet(y, { start: () => (dragged.current = true), release }) : undefined}
        style={{ ...sheetBox(def), y, opacity: shown, overflowY: drag ? "hidden" : "auto" }}
      >
        {children}
      </motion.div>
    </>
  );
}

/** AOSP's dialog window animation (React Navigation's DialogAndroid): scaling from 90% over 220ms (decelerating, power 5), fading over 150ms (power 3), the dim at 60% in 132ms. */
const DIALOG = {
  from: 0.9,
  to: 0.9,
  dim: 0.6,
  timing: { scale: { duration: 0.22, ease: decelerate5 }, opacity: { duration: 0.15, ease: decelerate3 } } as Transition,
  dimTiming: { duration: 0.132, ease: "linear" } as Transition,
};

/** A dialog, as Android's come and go: from 90% as it fades in, back to 90% as it fades out. */
function Dialog({ def, close, children }: { def: PartDef; close: () => void; children: ReactNode }) {
  return (
    <>
      <motion.div style={SCRIM} initial={{ opacity: 0 }} animate={{ opacity: DIALOG.dim }} exit={{ opacity: 0 }} transition={DIALOG.dimTiming} onClick={def.dismiss.includes("scrim") ? close : undefined} />
      <div style={CENTRE}>
        <motion.div role="alertdialog" aria-modal initial={{ opacity: 0, scale: DIALOG.from }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: DIALOG.to }} transition={DIALOG.timing} style={{ width: def.width, pointerEvents: "auto" }}>
          {children}
        </motion.div>
      </div>
    </>
  );
}

/** A snackbar (MDC's BaseTransientBottomBar, with M3's motionDurationLong2 and emphasized easing): up from below in 500ms, and back down. */
const TOAST = { duration: 0.5, ease: emphasized } satisfies Transition;

function Toast({ def, children }: { def: PartDef; children: ReactNode }) {
  return (
    <motion.div role="status" style={TOAST_BOX} initial={{ y: "100%" }} animate={{ y: 0 }} exit={{ y: "100%" }} transition={TOAST}>
      <div style={{ width: def.width, pointerEvents: "auto" }}>{children}</div>
    </motion.div>
  );
}

/** A Material 3 menu (material-web's md-menu): it unfolds from its edge in 500ms (emphasized), the surface fading in over 50ms; it folds to 35% in 150ms (emphasized accelerate), fading in the last 50ms. */
const MENU = {
  in: { clipPath: { duration: 0.5, ease: emphasized }, opacity: { duration: 0.05, ease: "linear" } } as Transition,
  out: { clipPath: { duration: 0.15, ease: [0.3, 0, 0.8, 0.15] }, opacity: { duration: 0.05, delay: 0.1, ease: "linear" } } as Transition,
  folded: 65,
};

function Menu({ def, anchor, size, close, children }: { def: PartDef; anchor?: Box; size: Size; close: () => void; children: ReactNode }) {
  const { pos, below } = menuPlace(anchor, size, def.width);
  // Unfolding from the edge next to what opened it: the top when it opens below, the bottom above.
  const fold = (hidden: number) => (below ? "inset(0% 0% " + hidden + "% 0%)" : "inset(" + hidden + "% 0% 0% 0%)");
  return (
    <>
      <div style={MENU_BACKDROP} onClick={def.dismiss.includes("scrim") ? close : undefined} />
      <motion.div
        role="menu"
        style={pos}
        initial={{ clipPath: fold(100), opacity: 0 }}
        animate={{ clipPath: fold(0), opacity: 1, transition: MENU.in, transitionEnd: { clipPath: "none" } }}
        exit={{ clipPath: fold(MENU.folded), opacity: 0, transition: MENU.out }}
      >
        {children}
      </motion.div>
    </>
  );
}

export interface PrototypeProps {
  start?: ScreenId;
  /** Where to begin instead: a state worked out ahead (a step of a walkthrough), and how far its screen is scrolled. */
  from?: { state: State; y?: number };
  /** Told each time the prototype moves. */
  onChange?: (s: State) => void;
}

export default function Prototype({ start = "rideChooseARide", from, onChange }: PrototypeProps) {
  const [nav, setNav] = useState<State>(() => from?.state ?? initial(start));
  const reduced = useReducedMotion() ?? false;
  const device = useRef<HTMLDivElement>(null);
  const scroller = useRef<HTMLElement | null>(null);
  const current = useRef(nav);
  current.current = nav;
  const changed = useRef(onChange);
  changed.current = onChange;
  useEffect(() => changed.current?.(nav), [nav]);
  // Begun part way: the screen is where it was scrolled to.
  const begun = useRef(from);
  useEffect(() => {
    if (begun.current?.y) scroller.current?.scrollTo({ top: begun.current.y });
  }, []);
  // A link back closes what's open on the screen first, like a rule's Back.
  const go = useCallback((to: ScreenId | "back", via: Via) => setNav((n) => (to === "back" && topOverlay(n) ? step(n, { do: "close" }) : move(n, to, via))), []);
  const act = useCallback((a: Action, e?: TapEvent) => {
    const el = e?.currentTarget instanceof Element ? e.currentTarget : null;
    const d = device.current?.getBoundingClientRect();
    const r = el?.getBoundingClientRect();
    const anchor = d && r ? { x: r.left - d.left, y: r.top - d.top, w: r.width, h: r.height } : undefined;
    setNav((n) => step(n, a, anchor));
  }, []);
  // Escape is Back while an overlay that Back closes is open.
  useEffect(() => {
    const onKey = (e: globalThis.KeyboardEvent) => {
      const n = current.current;
      const top = topOverlay(n);
      if (e.key !== "Escape" || !top || !PARTS[n.screen]?.[top]?.dismiss.includes("back")) return;
      e.preventDefault();
      e.stopPropagation();
      setNav((m) => step(m, { do: "back" }));
    };
    window.addEventListener("keydown", onKey, true);
    return () => window.removeEventListener("keydown", onKey, true);
  }, []);
  // A rule asked to scroll (a chip to its section): the screen scrolls there, smoothly.
  useEffect(() => {
    if (nav.scrollTo) scroller.current?.scrollTo({ top: nav.scrollTo.y, behavior: "smooth" });
  }, [nav.scrollTo]);
  const { Screen, width, height } = SCREENS[nav.screen];
  const via = calm(nav.via, reduced);
  return (
    <div ref={device} style={{ position: "relative", width, height, overflow: "hidden", isolation: "isolate" }}>
      <style>{qalamCSS}</style>
      <MotionConfig transition={via?.transition ?? MOTION.morph} reducedMotion="user">
        <AnimatePresence initial={false} custom={via}>
          <motion.div
            key={nav.visit}
            ref={(el: HTMLDivElement | null) => {
              if (el) scroller.current = el;
            }}
            custom={via}
            variants={screenVariants}
            initial={via?.kind === "smart" ? "smart" : "enter"}
            animate="center"
            exit="exit"
            layoutScroll
            onScroll={(e) => act({ do: "scrolled", y: e.currentTarget.scrollTop, max: e.currentTarget.scrollHeight - e.currentTarget.clientHeight })}
            // Each visit is its own stacking context: what's pinned in it stays under the overlays.
            style={{ position: "absolute", inset: 0, overflowX: "hidden", overflowY: "auto", isolation: "isolate" }}
          >
            <LayoutGroup id={`flow-${nav.group}`}>
              <Screen go={go} via={nav.via} act={act} open={nav.open} s={nav} />
            </LayoutGroup>
          </motion.div>
        </AnimatePresence>
        <Overlays s={nav} size={{ width, height }} act={act} reduced={reduced} />
      </MotionConfig>
    </div>
  );
}
